<?php require '../includes/layout.php'; require_role(['admin']); $d=db();
if($_SERVER['REQUEST_METHOD']==='POST'){ check_csrf(); $action=$_POST['action']??'save'; $id=(int)($_POST['id']??0);
 if($action==='delete'){ try{$d->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('Category deleted.');}catch(PDOException $x){flash('Category has products. Move or delete those products first.','err');}go('admin/categories.php'); }
 $name=trim($_POST['name']??'');$sort=max(0,(int)($_POST['sort_order']??0)); if(!$name){flash('Category name is required.','err');go('admin/categories.php');}
 try{if($id)$d->prepare('UPDATE categories SET name=?,sort_order=? WHERE id=?')->execute([$name,$sort,$id]);else$d->prepare('INSERT INTO categories(name,sort_order) VALUES(?,?)')->execute([$name,$sort]);log_act($id?'category updated':'category created');flash('Category saved.');}catch(PDOException $x){flash('Could not save category.','err');}go('admin/categories.php');}
$cats=$d->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name')->fetchAll();$ed=['id'=>0,'name'=>'','sort_order'=>count($cats)+1];if(isset($_GET['edit']))foreach($cats as $c)if($c['id']==(int)$_GET['edit'])$ed=$c;
head('Categories'); ?><div class="flex flex-wrap items-end justify-between gap-3 mb-4"><div><p class="text-xs font-semibold uppercase tracking-[.2em] text-mute">Menu organization</p><h1 class="text-2xl font-semibold mt-1">Categories</h1></div><?php if($ed['id']):?><a href="categories.php" class="text-sm text-[#C978A1] hover:underline">Add category</a><?php endif?></div>
<form method="post" class="<?=card('p-4 mb-5 grid gap-3 sm:grid-cols-[1fr_10rem_auto] items-end')?>"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$ed['id']?>"><label class="text-sm">Name<input class="<?=INP?> mt-1" name="name" value="<?=e($ed['name'])?>" required></label><label class="text-sm">Sort order<input class="<?=INP?> mt-1" name="sort_order" type="number" min="0" value="<?=e($ed['sort_order'])?>"></label><button class="<?=BTN?>"><?=$ed['id']?'Update':'Add'?></button></form>
<div class="<?=card('overflow-x-auto')?>"><table class="w-full min-w-[34rem] text-sm"><thead><tr class="text-left text-xs uppercase tracking-wide text-mute"><th class="p-3">Category</th><th>Order</th><th>Products</th><th class="p-3 text-right">Actions</th></tr></thead><tbody><?php foreach($cats as $c):?><tr class="border-t border-line"><td class="p-3 font-medium"><?=e($c['name'])?></td><td><?=$c['sort_order']?></td><td><?=$c['product_count']?></td><td class="p-3 text-right whitespace-nowrap"><a class="mr-3 underline" href="?edit=<?=$c['id']?>">Edit</a><form method="post" class="inline" onsubmit="return confirm('Delete this category?')"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="text-red-700 underline">Delete</button></form></td></tr><?php endforeach?></tbody></table></div><?php foot();
